// appendRest appends m's groups and data to dst.
func (m *ExecutionReport) appendRest(dst []byte) []byte {
	dst = appendMiscFees(dst, m.MiscFees)
	{
		var l [1]byte
		putUint8(l[:], uint8(len(m.ClOrdID)))
		dst = append(dst, l[:]...)
	}
	dst = append(dst, m.ClOrdID...)
	{
		var l [1]byte
		putUint8(l[:], uint8(len(m.OrigClOrdID)))
		dst = append(dst, l[:]...)
	}
	dst = append(dst, m.OrigClOrdID...)
	{
		var l [1]byte
		putUint8(l[:], uint8(len(m.Symbol)))
		dst = append(dst, l[:]...)
	}
	dst = append(dst, m.Symbol...)
	{
		var l [1]byte
		putUint8(l[:], uint8(len(m.SecondarySymbol)))
		dst = append(dst, l[:]...)
	}
	dst = append(dst, m.SecondarySymbol...)
	{
		var l [1]byte
		putUint8(l[:], uint8(len(m.CounterSymbol)))
		dst = append(dst, l[:]...)
	}
	dst = append(dst, m.CounterSymbol...)
	{
		var l [2]byte
		putUint16(l[:], uint16(len(m.ErrorText)))
		dst = append(dst, l[:]...)
	}
	dst = append(dst, m.ErrorText...)
	return dst
}

// AppendTo appends m to dst, its header included, the header's elements
// other than SBE's zero: AppendWithHeader sets them. It fails without
// appending if a data field or a group does not fit its encoding.
func (m *ExecutionReport) AppendTo(dst []byte) ([]byte, error) {
	return m.AppendWithHeader(dst, MessageHeader{})
}

// AppendWithHeader appends m to dst after header h, whose elements SBE
// defines, blockLength, templateId, schemaId, version, are set from m and the
// schema, its others written as they are. It fails without appending if a data
// field or a group does not fit its encoding.
func (m *ExecutionReport) AppendWithHeader(dst []byte, h MessageHeader) ([]byte, error) {
	if err := m.check(); err != nil {
		return dst, err
	}
	h.BlockLength = 281
	h.TemplateId = 98
	h.SchemaId = SchemaID
	h.Version = SchemaVersion
	dst, b := extend(dst, HeaderSize+281)
	h.putTo(b[:HeaderSize])
	m.putBlock(b[HeaderSize:])
	return m.appendRest(dst), nil
}

// Decode decodes m from b, a message with its header, and returns the
// length of the message, header included: the bytes after it are not read.
// Its []byte fields alias b. On error, m is left zero and the length is 0.
func (m *ExecutionReport) Decode(b []byte) (int, error) {
	h, body, err := ReadHeader(b)
	if err == nil && uint64(h.SchemaId) != SchemaID {
		err = ErrSchema
	}
	if err != nil {
		*m = ExecutionReport{}
		return 0, err
	}
	n, err := m.DecodeBody(h, body)
	if err != nil {
		return 0, err
	}
	return HeaderSize + n, nil
}

// DecodeBody decodes m from body, the message body after header h, and
// returns the length of the body: its root block of h's blockLength,
// padding or a newer version's fields included, its groups and its data,
// those of a newer version being ErrNewer. Its []byte fields alias body.
// On error, m is left zero and the length is 0.
func (m *ExecutionReport) DecodeBody(h MessageHeader, body []byte) (int, error) {
	if uint64(h.TemplateId) != ExecutionReportTemplateID {
		*m = ExecutionReport{}
		return 0, ErrTemplate
	}
	// Bounded before they become ints, which a wide one would wrap.
	if uint64(h.BlockLength) > uint64(len(body)) {
		*m = ExecutionReport{}
		return 0, ErrShort
	}
	version := int(min(uint64(h.Version), 1<<31-1))
	entries := 0
	n, err := m.decode(body, int(h.BlockLength), version, 0, 0, &entries)
	if err != nil {
		*m = ExecutionReport{}
		return 0, err
	}
	return n, nil
}

// MiscFees is an entry of the group MiscFees.
type MiscFees struct {
	// (id 25053)
	Exponent int8
	// (id 137)
	MiscFeeAmt int64
	// (id 139)
	MiscFeeType MiscFeeType
	// (id 138)
	MiscFeeCurr []byte
}

// decode decodes m from b: a block of blockLen bytes, then groups and
// data, numGroups and numData of them in all if its header or dimension
// counts them, 0 otherwise. It returns the bytes it read.
func (m *MiscFees) decode(b []byte, blockLen, version int, numGroups, numData uint64, entries *int) (int, error) {
	if len(b) < blockLen {
		return 0, ErrShort
	}
	_ = entries
	if blockLen < 10 {
		return 0, ErrMalformed
	}
	m.Exponent = getInt8(b[0:])
	m.MiscFeeAmt = getInt64(b[1:])
	m.MiscFeeType = MiscFeeType(getUint8(b[9:]))
	pos := blockLen
	// A newer version's groups, which nothing tells of, would be here:
	// what follows cannot be found with certainty.
	if version > SchemaVersion {
		return 0, ErrNewer
	}
	{
		if len(b)-pos < 1 {
			return 0, ErrShort
		}
		l := uint64(getUint8(b[pos:]))
		pos += 1
		if l > 254 {
			return 0, ErrMalformed
		}
		if uint64(len(b)-pos) < l {
			return 0, ErrShort
		}
		m.MiscFeeCurr = b[pos : pos+int(l) : pos+int(l)]
		pos += int(l)
	}
	// A newer version's data, which nothing tells of, would be here:
	// what follows cannot be found with certainty.
	if version > SchemaVersion {
		return 0, ErrNewer
	}
	return pos, nil
}

// check reports whether m's groups and data fit their encodings.
func (m *MiscFees) check() error {
	if uint64(len(m.MiscFeeCurr)) > 254 {
		return ErrLength
	}
	return nil
}

// putBlock encodes m's fields into b, its zeroed block.
func (m *MiscFees) putBlock(b []byte) {
	_ = b[9]
	putInt8(b[0:], m.Exponent)
	putInt64(b[1:], m.MiscFeeAmt)
	putUint8(b[9:], uint8(m.MiscFeeType))
}

// appendRest appends m's groups and data to dst.
func (m *MiscFees) appendRest(dst []byte) []byte {
	{
		var l [1]byte
		putUint8(l[:], uint8(len(m.MiscFeeCurr)))
		dst = append(dst, l[:]...)
	}
	dst = append(dst, m.MiscFeeCurr...)
	return dst
}

func decodeMiscFees(s *[]MiscFees, b []byte, version int, entries *int) (int, error) {
	if len(b) < SmallGroupSize16EncodingSize {
		return 0, ErrShort
	}
	var d SmallGroupSize16Encoding
	d.decodeFrom(b[:SmallGroupSize16EncodingSize], version)
	count := uint64(d.NumInGroup)
	pos := SmallGroupSize16EncodingSize
	if count == 0 {
		*s = (*s)[:0]
		return pos, nil
	}
	// The block length and the count are bounded by the bytes left before
	// they become ints, which a wide one would wrap.
	if uint64(d.BlockLength) > uint64(len(b)-pos) {
		return 0, ErrShort
	}
	blockLen := int(d.BlockLength)
	// An entry takes at least its block, its groups' dimensions and its
	// data's lengths: what the bytes left allow bounds the count.
	minEntry := blockLen
	minEntry += 1
	if minEntry == 0 {
		return 0, ErrMalformed
	}
	if count > uint64((len(b)-pos)/minEntry) {
		return 0, ErrShort
	}
	n := int(count)
	if *entries += n; *entries > MaxEntries {
		return 0, ErrEntries
	}
	if cap(*s) < n {
		*s = make([]MiscFees, n)
	} else {
		*s = (*s)[:n]
	}
	for i := range *s {
		c, err := (*s)[i].decode(b[pos:], blockLen, version, 0, 0, entries)
		if err != nil {
			return 0, err
		}
		pos += c
	}
	return pos, nil
}

func appendMiscFees(dst []byte, s []MiscFees) []byte {
	var d SmallGroupSize16Encoding
	d.BlockLength = 10
	d.NumInGroup = uint16(len(s))
	dst, b := extend(dst, SmallGroupSize16EncodingSize)
	d.putTo(b)
	for i := range s {
		dst, b = extend(dst, 10)
		s[i].putBlock(b)
		dst = s[i].appendRest(dst)
	}
	return dst
}
